int get_dccp_sockopt(struct sock *sk, int optname, int len, u32 __user *optval, int __user *optlen)
{
    int err = 0;
    struct tfrc_tx_info info;

    if (optname == DCCP_SOCKOPT_CCID_TX_INFO) {
        if (len < sizeof(info))
            return -EINVAL;

        /* Populate tx info from socket state */
        info.delivery_rate    = sk->sk_tx_rate;
        info.pktSchedTime    = sk->sk_pacing_rate;
        info.pktTxTime       = sk->sk_tx_timestamp;
        info.pktLost         = sk->sk_retransmits;
        info.pktDup          = sk->sk_retransmits;
        info.pktRetrans      = sk->sk_retransmits;

        /* Set output length */
        if (put_user(sizeof(info), optlen))
            return -EFAULT;

        /* Copy data to user space */
        if (copy_to_user(optval, &info, sizeof(info)))
            return -EFAULT;
    } else {
        return -EINVAL;
    }

    return err;
}

#include <linux/dccp.h>
#include <linux/uaccess.h>
#include <net/sock.h>

int dccp_getsockopt(struct sock *sk, int optname, int len, u32 __user *optval, int __user *optlen)
{
    struct tfrc_tx_info tx_info;
    int ret = 0;

    if (optname == DCCP_SOCKOPT_CCID_TX_INFO) {
        if (len < sizeof(tx_info))
            return -EINVAL;

        tx_info.tx_packets = sk->sk_wmem_alloc;
        tx_info.tx_bytes = sk->sk_wmem_allocated;
        tx_info.tx_time = jiffies;

        if (put_user(sizeof(tx_info), optlen) ||
            copy_to_user(optval, &tx_info, sizeof(tx_info)))
            ret = -EFAULT;
    } else {
        ret = -EINVAL;
    }

    return ret;
}

int get_dccp_sockopt(struct sock *sk, int optname, int len, u32 __user *optval, int __user *optlen)
{
    int ret = 0;
    struct tfrc_tx_info tx_info;

    if (optname == DCCP_SOCKOPT_CCID_TX_INFO) {
        if (len < sizeof(tx_info))
            return -EINVAL;

        memset(&tx_info, 0, sizeof(tx_info));
        tx_info = ((struct dccp_sock *)sk)->tx_info;

        if (copy_to_user(optval, &tx_info, sizeof(tx_info)) ||
            put_user(sizeof(tx_info), optlen)) {
            return -EFAULT;
        }
    } else {
        ret = -ENOPROTOOPT;
    }

    return ret;
}

int get_dccp_sockopt(struct sock *sk, int optname, int len, u32 __user *optval, int __user *optlen)
{
    int ret = 0;
    struct tfrc_tx_info tx_info;

    if (optname == DCCP_SOCKOPT_CCID_TX_INFO) {
        if (len < sizeof(tx_info))
            return -EINVAL;

        tx_info = sk->dccps_hc_tx_info;

        if (copy_to_user(optval, &tx_info, sizeof(tx_info)) != 0)
            return -EFAULT;

        if (put_user(sizeof(tx_info), optlen) != 0)
            return -EFAULT;
    } else {
        ret = -EINVAL;
    }

    return ret;
}
